//! SpecFrame `ref_pos` and FluxFrame `density_system` / `density_unit`,
//! checked against C's `astGetRefPos`, `astGetDensitySystem` and
//! `astGetDensityUnit`. `TimeFrame::current_time` is checked inside the
//! crate (timeframe.rs), at the clock reading C used.
//!
//! `frame_api_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/frame_api_probe.c`.

// The clock cases are checked inside the crate (timeframe.rs).
#[allow(dead_code)]
#[rustfmt::skip]
#[path = "frame_api_oracle/cases.rs"]
mod cases;

use starlink_ast::frames::{
    FluxFrame, FluxSystem, Frame, SkyFrame, SkySystem, SpecFrame, SpecSystem,
};

#[test]
fn ref_pos_follows_the_c_library() {
    let mut sf = SpecFrame::new(SpecSystem::Wavelen);
    sf.set_ref_pos(None, 1.0, 0.3).unwrap();
    let gal = SkyFrame::new(SkySystem::Galactic);
    let mut fk4 = SkyFrame::new(SkySystem::Fk4);
    fk4.set_equinox_year(1950.0);
    fk4.perm_axes(&[2, 1]).unwrap();
    let got = [
        ("none", sf.ref_pos(None).unwrap()),
        ("galactic", sf.ref_pos(Some(&gal)).unwrap()),
        ("fk4_swapped", sf.ref_pos(Some(&fk4)).unwrap()),
    ];
    assert_eq!(
        got.len(),
        cases::REF_POS.len(),
        "the test runs every case the C probe recorded"
    );
    for ((name, (lon, lat)), &(want_name, want)) in got.iter().zip(cases::REF_POS) {
        assert_eq!(*name, want_name);
        crate::common::assert_c_values(&[*lon, *lat], &want, name);
    }
}

#[test]
fn density_follows_the_c_library() {
    let mut by_unit = FluxFrame::unset_system();
    Frame::set_unit(&mut by_unit, 1, "W/m^2/Angstrom").unwrap();
    let got = [
        ("System=FLXDN", FluxFrame::new(FluxSystem::FluxDen)),
        ("System=SFCBRW", FluxFrame::new(FluxSystem::SBrightW)),
        ("Unit=W/m^2/Angstrom", by_unit),
    ];
    assert_eq!(
        got.len(),
        cases::DENSITY.len(),
        "the test runs every case the C probe recorded"
    );
    for ((name, ff), &(want_name, system, unit)) in got.iter().zip(cases::DENSITY) {
        assert_eq!(*name, want_name);
        assert_eq!(ff.density_system().unwrap().as_str(), system, "{name}");
        assert_eq!(ff.density_unit().unwrap(), unit, "{name}");
    }
}
